def profile(root, x, w, t, interval):
    if root["kind"] == "STATE":
        return Atom(root["relation"], w, x, t)
    return Atom("CAPABLE", w, x,
                EventSchema(root["relation"], root["grade"], x, interval))

def realized(root, x, w, t, interval, event):
    if root["kind"] == "STATE":
        return And(Atom(root["relation"], w, x, t),
                   WitnessPackage(event, And(Atom("ACTUAL", w, event),
                       Atom("ATTAINS_STATE", w, event, x, root["relation"]),
                       Atom("BEFORE", EventEnd(w, event), t))))
    clauses = [Atom("ACTUAL", w, event),
               Atom(root["relation"], w, event, x, interval)]
    if root["grade"] == "CONTINUOUS":
        clauses.append(Atom("CONTINUOUS_FULL_PHASE", w, event, interval))
    return WitnessPackage(event, And(*clauses))

def realize_frame(formula, frame, x, w):
    if frame == "QOK_NOMINAL_LIQUID":
        return And(Atom("LIQUID", w, x), formula)
    return formula
